hand['files']={str(f.relative_to(D)):sha(f)for f in sorted(D.rglob('*'))if f.is_file()and f.name!='route-handoff.json'};write(D/'route-handoff.json',hand);assert all(sha(D/k)==v for k,v in hand['files'].items());print(json.dumps(dict(board_sha256=h,handoff_sha256=sha(D/'route-handoff.json'),files=len(hand['files']),status=hand['status'])))
